package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;

@SpringBootApplication
@ConfigurationPropertiesScan
public class DemoApplication {

    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}

package com.example.demo;

import org.springframework.boot.context.properties.ConfigurationProperties;

@ConfigurationProperties(prefix = "demo")
public class DemoProperties {

    private String brand = "default-brand";
    private int retries = 3;

    public String getBrand() {
        return brand;
    }

    public void setBrand(String brand) {
        this.brand = brand;
    }

    public int getRetries() {
        return retries;
    }

    public void setRetries(int retries) {
        this.retries = retries;
    }
}

package com.example.demo;

import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    /** Deliberately secret looking, to prove the stub does not leak constants. */
    private static final String INTERNAL_SALT = "internal-salt-9f3a";

    private final DemoProperties properties;

    public GreetingService(DemoProperties properties) {
        this.properties = properties;
    }

    public String greet(String name) {
        return "hello, " + name + " from " + properties.getBrand();
    }

    public int retries() {
        return properties.getRetries();
    }

    public String saltFingerprint() {
        return INTERNAL_SALT.substring(0, 8) + "-" + Integer.toHexString(INTERNAL_SALT.hashCode());
    }
}

package com.example.demo;

import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class HelloController {

    private final GreetingService service;

    public HelloController(GreetingService service) {
        this.service = service;
    }

    @GetMapping("/hello")
    public Map<String, Object> hello(@RequestParam(defaultValue = "world") String name) {
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("message", service.greet(name));
        body.put("retries", service.retries());
        body.put("salt", service.saltFingerprint());
        return body;
    }

    @GetMapping("/ping")
    public String ping() {
        return "pong";
    }
}
